    def score_hand_helper(hand: list[str], scoring_db: dict[str, dict[str, Any]]) -> list[tuple[str, float]]:
        scored = []
        for card_name in hand:
            card_name_str = str(card_name)
            entry = scoring_db.get(card_name_str.lower(), {})
            ev_score = float(entry.get('ev_score', 0.0))
            scored.append((card_name_str, ev_score))
        return scored

    def mean_ev_helper(scored_cards: list[tuple[str, float]]) -> float:
        if not scored_cards:
            return 0.0
        return sum((ev for _, ev in scored_cards)) / len(scored_cards)

    def derive_profile_helper(hand_score: float, thresholds: list[tuple[float, str]]) -> str:
        for threshold, profile in thresholds:
            if hand_score >= threshold:
                return profile
        return 'defensive'

    def best_card_helper(scored_cards: list[tuple[str, float]]) -> str:
        if not scored_cards:
            return '(empty hand)'
        return max(scored_cards, key=lambda t: t[1])[0]

    # === agents/hand_analyst_prizes ===

    class HandPrizesMixin:

        def evaluate_prizes(self, hand: List[str], discard: List[str], board: List[str], deck_base_list: Dict[int, int], deck_remaining: int, has_searched_deck: bool=False) -> tuple[int, int, Dict[str, float]]:
            revealed_counts = {}
            for cid in hand + discard + board:
                try:
                    cid_int = int(cid)
                    revealed_counts[cid_int] = revealed_counts.get(cid_int, 0) + 1
                except:
                    pass
            total_revealed_count = sum(revealed_counts.values())
            total_starting_count = sum(deck_base_list.values()) if deck_base_list else 60
            total_unrevealed = max(0, total_starting_count - total_revealed_count)
            prize_remaining = max(0, total_unrevealed - deck_remaining)
            prized_probabilities = {}
            if has_searched_deck:
                return (prize_remaining, total_unrevealed, prized_probabilities)
            if total_unrevealed > 0 and prize_remaining > 0:

                def nCr(n, r):
                    if r < 0 or r > n:
                        return 0
                    return math.comb(n, r)
                for cid_int, start_count in deck_base_list.items():
                    rev_count = revealed_counts.get(cid_int, 0)
                    n_unrevealed = max(0, start_count - rev_count)
                    if n_unrevealed > 0:
                        prob = 1.0 - nCr(total_unrevealed - n_unrevealed, prize_remaining) / nCr(total_unrevealed, prize_remaining)
                        prized_probabilities[str(cid_int)] = round(prob, 4)
                    else:
                        prized_probabilities[str(cid_int)] = 0.0
            return (prize_remaining, total_unrevealed, prized_probabilities)

    # === agents/log_flusher ===
    """
    agents/log_flusher.py

    Shared utility for flushing in-memory reasoning log buffers to JSON files.
    Handles reading existing logs, merging, and writing back atomically.
    """

    class FileLock:
        """Atomic cross-platform file locking manager using OS-level O_EXCL flags."""

        def __init__(self, filepath: Path, timeout: float=5.0):
            self.lockfile = Path(str(filepath) + '.lock')
            self.timeout = timeout
            self.dummy = False

        def __enter__(self):
            start = time.time()
            while True:
                try:
                    fd = os.open(self.lockfile, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                    os.close(fd)
                    return self
                except FileExistsError:
                    if time.time() - start > self.timeout:
                        try:
                            self.lockfile.unlink(missing_ok=True)
                        except:
                            pass
                    time.sleep(0.05)
                except Exception:
                    self.dummy = True
                    return self

        def __exit__(self, exc_type, exc_val, exc_tb):
            if not self.dummy:
                try:
                    self.lockfile.unlink(missing_ok=True)
                except:
                    pass

    def flush_reasoning_logs(buffer: List[dict], filepath: Path, log: logging.Logger) -> None:
        """
        Write all buffered log entries to *filepath*, merging with any
        existing entries already on disk.  Clears *buffer* on success.
        Protected by atomic file locking.
        """
        if not buffer:
            return
        with FileLock(filepath):
            try:
                logs = _read_existing_logs(filepath)
                logs.extend(buffer)
                filepath.write_text(json.dumps(logs, indent=2), encoding='utf-8')
                buffer.clear()
            except Exception as e:
                log.error(f'Failed to flush reasoning logs to {filepath}: {e}')

    def _read_existing_logs(filepath: Path) -> list:
        """Return the list of log entries already stored in *filepath*."""
        if not filepath.exists():
            return []
        content = filepath.read_text(encoding='utf-8').strip()
        if not content:
            return []
        try:
            data = json.loads(content)
            return data if isinstance(data, list) else [data]
        except json.JSONDecodeError:
            return []

    # === agents/mcts_mast ===

    class MASTPolicy:
        """Tracks action -> win statistics across all MCTS rollouts."""

        def __init__(self, exploration_weight: float=0.3):
            self.action_wins: Dict[str, int] = defaultdict(int)
            self.action_visits: Dict[str, int] = defaultdict(int)
            self.exploration_weight = exploration_weight

        def update(self, actions_played: List[str], won: bool):
            """Update statistics after a rollout completes."""
            for action in actions_played:
                self.action_visits[action] += 1
                if won:
                    self.action_wins[action] += 1

        def get_action_prior(self, action: str) -> float:
            """Blend MAST statistics with default policy prior."""
            if self.action_visits[action] == 0:
                return 0.5
            return self.action_wins[action] / self.action_visits[action]

        def select_rollout_action(self, legal_actions: List[str]) -> str:
            """ε-greedy: exploration_weight chance of random, else pick highest win-rate."""
            if not legal_actions:
                return None
            if random.random() < self.exploration_weight:
                return random.choice(legal_actions)
            best_action = None
            best_rate = -1.0
            for action in legal_actions:
                if self.action_visits[action] == 0:
                    rate = 1.0
                else:
                    rate = self.action_wins[action] / self.action_visits[action]
                if rate > best_rate:
                    best_rate = rate
                    best_action = action
            return best_action if best_action is not None else random.choice(legal_actions)

    # === agents/opponent_model_helpers ===
    """
    agents/opponent_model_helpers.py

    Helper logic for OpponentModel: archetype classification and action predictions.
    """
    KEY_ID_TO_ARCHETYPE = {'1092': 'setup', '721': 'aggro', '722': 'aggro', '1145': 'stall', '1163': 'stall', '1121': 'control', '1262': 'combo'}

    def identify_opponent_archetype(revealed_state: List[Any], archetypes: Dict[str, Any]) -> tuple[str, float]:
        """Identifies archetype and returns (archetype_name, confidence)."""
        for card in revealed_state:
            if str(card) in KEY_ID_TO_ARCHETYPE:
                return (KEY_ID_TO_ARCHETYPE[str(card)], 0.99)
        total_revealed = len(revealed_state)
        if total_revealed < 3 or not archetypes:
            return ('unknown', 0.0)
        best_match_count = 0
        best_archetype = 'unknown'
        for arch_name, arch_data in archetypes.items():
            signature_cards = set(arch_data.get('signature_cards', []))
            card_pool = set(arch_data.get('card_pool', []))
            matches = sum((1 for c in revealed_state if c in signature_cards or c in card_pool))
            if matches > best_match_count:
                best_match_count = matches
                best_archetype = arch_name
        if best_match_count > 0:
            return (best_archetype, round(best_match_count / total_revealed, 4))
        return ('unknown', 0.0)

    def predict_opponent_action(archetype: str, prizes_remaining: int, turn_number: int) -> str:
        """Predicts next opponent action based on archetype and state variables."""
        if archetype == 'aggro':
            return 'attack' if prizes_remaining < 6 else 'attach_energy'
        elif archetype == 'control':
            return 'play_trainer_disruption' if prizes_remaining <= 3 else 'stall'
        elif archetype == 'combo':
            return 'execute_combo' if turn_number >= 3 else 'setup_bench'
        return 'unknown'

    # === agents/orchestrator_belief ===
    class OrchestratorBeliefMixin:

        def sync_belief_tracker(self, game_state: dict):
            """Synchronizes the belief tracker state with the current public game state.
            Calls update_on_* methods for detected opponent actions to keep known_in_hand accurate.
            """
            prev_hand_size = self.belief_tracker.state.hand_size
            prev_discard_len = len(self.belief_tracker.state.known_in_discard)
            self.belief_tracker.state.hand_size = game_state.get('opponent_hand_count', 5)
            self.belief_tracker.state.prize_size = game_state.get('opponent_prizes', 6)
            hand_diff = self.belief_tracker.state.hand_size - prev_hand_size
            if hand_diff > 0:
                self.belief_tracker.update_on_draw(hand_diff)
            known_in_play = {}
            active = game_state.get('opponent_active')
            if active:
                active_id = active.get('id') if isinstance(active, dict) else active
                if active_id:
                    try:
                        known_in_play[int(active_id)] = 1
                        prev_play = self.belief_tracker.state.known_in_play
                        if int(active_id) not in prev_play:
                            self.belief_tracker.update_on_play(int(active_id))
                    except ValueError:
                        pass
            for bench_item in game_state.get('opponent_bench', []):
                bench_id = bench_item.get('id') if isinstance(bench_item, dict) else bench_item
                if bench_id:
                    try:
                        bench_id_int = int(bench_id)
                        known_in_play[bench_id_int] = known_in_play.get(bench_id_int, 0) + 1
                    except ValueError:
                        pass
            self.belief_tracker.state.known_in_play = known_in_play
            known_in_discard = {}
            for card_id in game_state.get('opponent_discard', []):
                try:
                    card_id_int = int(card_id)
                    known_in_discard[card_id_int] = known_in_discard.get(card_id_int, 0) + 1
                except ValueError:
                    pass
            for cid, cnt in known_in_discard.items():
                prev_cnt = self.belief_tracker.state.known_in_discard.get(cid, 0)
                if cnt > prev_cnt:
                    self.belief_tracker.update_on_discard(cid)
            self.belief_tracker.state.known_in_discard = known_in_discard
            total_cards = sum(self.belief_tracker.assumed_deck.values()) if self.belief_tracker.assumed_deck else 60
            known_non_deck = self.belief_tracker.state.hand_size + self.belief_tracker.state.prize_size + sum(known_in_play.values()) + sum(known_in_discard.values())
            self.belief_tracker.state.deck_size = max(0, total_cards - known_non_deck)
            self.belief_tracker._recalculate_probabilities()

