    # === agents/sequencing_engine ===

    class SequencingEngine:
        PHASE_ORDER = ['search', 'draw', 'board', 'attack']

        def get_phase(self, action: str) -> str:
            if action.startswith('play_trainer:'):
                action_suffix = action[13:].replace('_', ' ').replace("'", '').lower()
                registry = CardRegistry()
                for card in registry.cards.values():
                    c_name = card.card_name.replace("'", '').lower()
                    if c_name == action_suffix or action_suffix in c_name:
                        try:
                            heavy = registry.get_full_skill(card.card_id)
                        except Exception as e:
                            import logging
                            logging.error(f'get_full_skill failed: {e}')
                            continue
                        if heavy:
                            if heavy.combo_tags & ComboTag.SEARCH:
                                return 'search'
                            if heavy.combo_tags & ComboTag.DRAW:
                                return 'draw'
                        break
            elif action.startswith('attack:') or action == 'pass':
                return 'attack'
            return 'board'

        def group_actions(self, legal_actions: List[str]) -> Dict[str, List[str]]:
            groups = {phase: [] for phase in self.PHASE_ORDER}
            for action in legal_actions:
                phase = self.get_phase(action)
                groups[phase].append(action)
            return groups

        def sequence_actions(self, legal_actions: List[str], game_state) -> List[str]:
            groups = self.group_actions(legal_actions)
            prioritized = []
            for phase in self.PHASE_ORDER:
                prioritized.extend(groups[phase])
            return prioritized

    # === agents/state_cache ===
    logger = logging.getLogger(__name__)

    def board_hash(hand_ids: Tuple[int, ...], board_ids: Tuple[int, ...], deck_remaining: int, turn: int) -> int:
        """Computes a hash for the current board state."""
        return hash((hand_ids, board_ids, deck_remaining, turn))

    class CachedEvaluator:

        def __init__(self, evaluator_func):
            self.evaluator_func = evaluator_func
            self.hits = 0
            self.misses = 0
            self._cache: Dict[int, Dict[str, Any]] = {}

        def _eval(self, state_hash: int, **eval_kwargs) -> Dict[str, Any]:
            """Performs an evaluation and tracks cache misses."""
            self.misses += 1
            return self.evaluator_func(**eval_kwargs)

        def evaluate(self, hand_ids: list, board_ids: list, deck_remaining: int, turn: int, **kwargs) -> Dict[str, Any]:
            """Evaluates the board state, returning a cached result if available."""
            h_tuple = tuple(sorted(hand_ids))
            b_tuple = tuple(sorted(board_ids))
            h = board_hash(h_tuple, b_tuple, deck_remaining, turn)
            if h in self._cache:
                self.hits += 1
                return self._cache[h]
            result = self._eval(h, hand_ids=hand_ids, board_ids=board_ids, deck_remaining=deck_remaining, turn=turn, **kwargs)
            self._cache[h] = result
            return result

        def reset(self):
            """Clears the cache."""
            self._cache.clear()
            self.hits = 0
            self.misses = 0

        def get_stats(self) -> Dict[str, int]:
            return {'hits': self.hits, 'misses': self.misses}

    # === agents/strategy_agent ===
    """Board-strategy selection agent. Delegates I/O to strategy_agent_io."""
    _CONF_EXACT_KEY = 1.0
    _CONF_KEYWORD = 0.75
    _CONF_FALLBACK = 0.3
    _FALLBACK_PROFILE_KEY = 'hand_dead'

    class StrategyAgent:
        """Selects the best strategic posture for the current board state."""

        def __init__(self, **kwargs: Any) -> None:
            try:
                self._profiles: dict[str, dict[str, Any]] = load_skill(kwargs.get('skills_dir'))
            except Exception as e:
                self._profiles = {}

        def evaluate(self, packet: dict[str, Any]) -> dict[str, Any]:
            try:
                return self._evaluate_internal(packet)
            except Exception as e:
                return {'strategy': 'error_fallback', 'posture': 'tempo', 'actions': ['PASS'], 'escalation': 'PASS', 'confidence': 0.0}

        def _evaluate_internal(self, packet: dict[str, Any]) -> dict[str, Any]:
            if hasattr(packet, 'model_dump'):
                packet = packet.model_dump()
            elif hasattr(packet, '_asdict'):
                packet = packet._asdict()
            elif hasattr(packet, '__dict__'):
                packet = packet.__dict__
            if not isinstance(packet, dict):
                packet = {}
            trigger: str = str(packet.get('trigger', '')).strip()
            board_summary: dict = packet.get('board_summary', {})
            if board_summary.get('turn_number', packet.get('turn', 0)) == 1 and (not hasattr(self, '_checked_deck')):
                self._checked_deck = True
                deck = packet.get('deck', []) or board_summary.get('deck', [])
                if deck:
                    elements = set()
                    basics = 0
                    for cid in deck:
                        c = _registry.get(int(cid) if str(cid).isdigit() else cid)
                        if c and c.card_type.name == 'POKEMON':
                            basics += 1
                            try:
                                full = _registry.get_full_skill(int(cid))
                                if full and hasattr(full, 'element_type'):
                                    elements.add(full.element_type)
                            except Exception:
                                pass
                    if len(elements) >= 4 or (len(deck) > 20 and basics < 3):
                        import logging
                        logging.getLogger('StrategyAgent').error(f'CRITICAL WARNING: Executing with a highly unoptimized/brick-risk deck! Detected {len(elements)} elemental types.')
                        print(f'CRITICAL WARNING: Executing with a highly unoptimized/brick-risk deck! Detected {len(elements)} elemental types.')
            profile_key, profile, confidence, match_reason = self._match_profile(trigger, board_summary)
            result: dict[str, Any] = {'strategy': profile_key, 'posture': profile.get('posture', 'tempo'), 'actions': profile.get('actions', ['PASS']), 'escalation': profile.get('escalation', 'PASS'), 'confidence': round(confidence, 4)}
            self._log(packet, profile_key, match_reason, result)
            return result
        receive = evaluate

        def _match_profile(self, trigger: str, board_summary: dict[str, Any]) -> tuple[str, dict[str, Any], float, str]:
            trigger_lower = trigger.lower()
            if trigger_lower in self._profiles:
                return (trigger_lower, self._profiles[trigger_lower], _CONF_EXACT_KEY, 'exact key match')
            board_match = board_signal_match(board_summary)
            if board_match:
                key = board_match
                if key not in self._profiles:
                    raise ValueError(f"CRITICAL SILENT FAILURE PREVENTED: Strategy key '{key}' is missing from strategy_profiles.json!")
                return (key, self._profiles[key], _CONF_KEYWORD, f'board_summary signal -> {key}')
            best_key, best_score = keyword_scan(trigger_lower, self._profiles)
            if best_key and best_score > 0:
                return (best_key, self._profiles[best_key], _CONF_KEYWORD * best_score, f'keyword scan score={best_score:.2f}')
            if _FALLBACK_PROFILE_KEY not in self._profiles:
                raise ValueError(f"CRITICAL SILENT FAILURE PREVENTED: Fallback key '{_FALLBACK_PROFILE_KEY}' is missing from strategy_profiles.json!")
            fallback = self._profiles[_FALLBACK_PROFILE_KEY]
            return (_FALLBACK_PROFILE_KEY, fallback, _CONF_FALLBACK, 'no match -> fallback')

        def _log(self, packet: dict[str, Any], matched_key: str, match_reason: str, result: dict[str, Any]) -> None:
            log_strategy(packet, matched_key, match_reason, result, list(self._profiles.keys()))

    # === agents/turn_planner_logging ===
    """
    agents/turn_planner_logging.py

    Helper utilities for TurnPlanner: legal candidate generation and reasoning log management.
    """
    logger = logging.getLogger(__name__)

    def build_legal_candidates(game_state: dict) -> List[str]:
        """Build a list of legal action strings from game_state fields."""
        candidates = []
        for k, prefix in [('legal_attacks', 'attack'), ('legal_evolutions', 'evolve'), ('legal_attachments', 'attach_energy'), ('legal_trainers', 'play_trainer'), ('legal_bench', 'bench'), ('legal_retreats', 'retreat'), ('legal_abilities', 'ability')]:
            for val in game_state.get(k, []):
                candidates.append(f'{prefix}:{val}')
        candidates.append('pass')
        return candidates

    class TurnPlannerLogger:
        """Buffers per-turn reasoning entries and flushes them to disk."""

        def __init__(self, log_dir: Path):
            self.reasoning_log_file = log_dir / 'reasoning_log.json'
            self._reasoning_buffer: list = []

        def log_reasoning(self, turn: int, profile: str, response: dict):
            """Append a reasoning snapshot to the in-memory buffer."""
            self._reasoning_buffer.append({'turn': turn, 'priority_profile': profile, 'action_sequence': response['action_sequence'], 'primary_action': response['primary_action'], 'reasoning_chain': response['reasoning_chain']})

        def flush_logs(self):
            """Write all buffered logs to disk. Called once at end of game."""
            if self._reasoning_buffer:
                try:
                    self.reasoning_log_file.write_text(json.dumps(self._reasoning_buffer, indent=2), encoding='utf-8')
                except Exception as e:
                    logger.error(f'Failed to flush turn planner logs: {e}')
                self._reasoning_buffer.clear()

    # === agents/value_network ===

    def __getattr__(name):
        if name == 'HeuristicValueNetwork':
            return HeuristicValueNetwork
        raise AttributeError(f'module {__name__} no attr {name}')
    logger = logging.getLogger(__name__)

    @dataclass
    class ActionPrior:
        action: str
        prob: float

    class BaseValueNetwork(ABC):

        @abstractmethod
        def evaluate(self, game_state: dict, action: str | None=None, determinization: dict | None=None) -> float:
            pass

    class NeuralValueNetwork(BaseValueNetwork):
        heuristic: Any
        model: Any

        def __init__(self, weights_path='logs/model_weights.pth'):
            self.weights_path = Path(weights_path)
            self.heuristic = None
            self.model = None
            self._state_cache = {}
            if PTCGValueMLP is not None and self.weights_path.exists():
                try:
                    import torch
                    self.model = PTCGValueMLP()
                    self.model.load_state_dict(torch.load(str(self.weights_path), map_location='cpu'))
                    self.model.eval()
                except:
                    self.model = None
            if self.model is None:
                self.heuristic = HeuristicValueNetwork()

        def evaluate(self, game_state: dict, action: str | None=None, determinization: dict | None=None) -> float:
            if game_state.get('game_over'):
                return 1.0 if game_state.get('winner') == 'me' else -1.0
            if self.heuristic:
                return self.heuristic.evaluate(game_state, action, determinization)
            try:
                import torch
                hand_sorted = sorted([str(x) for x in game_state.get('my_hand', [])]) if isinstance(game_state.get('my_hand'), list) else []
                active = game_state.get('my_active_pokemon', {})
                active_id = str(active.get('id')) if isinstance(active, dict) else None
                active_attached_sorted = sorted([str(x) for x in active.get('attached', [])]) if isinstance(active, dict) else []
                bench_strs = sorted([str(x) for x in game_state.get('my_bench', [])]) if isinstance(game_state.get('my_bench'), list) else []
                opp_bench_strs = sorted([str(x) for x in game_state.get('opponent_bench', [])]) if isinstance(game_state.get('opponent_bench'), list) else []
                my_discard_size = len(game_state.get('my_discard_pile', [])) if isinstance(game_state.get('my_discard_pile'), list) else 0
                opp_discard_size = len(game_state.get('opponent_discard_pile', [])) if isinstance(game_state.get('opponent_discard_pile'), list) else 0
                stadium = game_state.get('stadium_card')
                h = hash((str(hand_sorted), str(game_state.get('turn_number', 0)), str(active_id), str(active_attached_sorted), str(bench_strs), str(opp_bench_strs), str(my_discard_size), str(opp_discard_size), str(stadium), game_state.get('my_active_damage', 0), game_state.get('my_prizes', 6), game_state.get('opponent_prizes', 6), game_state.get('opponent_active_hp', 100)))
                val = 0.0
                if self.model is not None and state_to_tensor is not None:
                    if h not in self._state_cache:
                        with torch.no_grad():
                            self._state_cache[h] = self.model(state_to_tensor(game_state)).item()
                    val = self._state_cache[h]
                if action:
                    val += _action_score(action, game_state, 0.0)
                return max(-1.0, min(1.0, val))
            except:
                return HeuristicValueNetwork().evaluate(game_state, action, determinization)

    class BasePolicyNetwork(ABC):

        @abstractmethod
        def get_priors(self, game_state: dict, legal_actions: List[str]) -> List:
            pass

    class HeuristicPolicyNetwork(BasePolicyNetwork):

        def get_priors(self, game_state: dict, legal_actions: List[str]) -> List[ActionPrior]:
            priors = []
            if not legal_actions:
                return priors
            pid = game_state.get('prized_card_ids', {})
            pc = game_state.get('prize_certainty', 0.0)
            bp = 1.0 / len(legal_actions)
            for a in legal_actions:
                p = bp
                if a.startswith('attack:'):
                    p *= 2.0
                elif a.startswith('evolve:'):
                    p *= 1.5
                elif a.startswith('attach_energy:'):
                    p *= 1.3
                elif a.startswith('ability:'):
                    p *= 1.5
                elif a.startswith('retreat:'):
                    p *= 1.2
                elif a.startswith('play_trainer:'):
                    if pc > 0 and sum(pid.values()) <= 2:
                        p *= 1.3
                priors.append(ActionPrior(action=a, prob=p))
            total = sum((pr.prob for pr in priors))
            if total > 0:
                for pr in priors:
                    pr.prob /= total
            return priors

