    """
    agents/time_manager.py
    ----------------------
    Monitors elapsed game time and enforces strict timeout-avoidance policy.

    Contract
    --------
    - No skill file -- operates on hard-wired timing thresholds only.
    - Input packet: { time_elapsed: float, time_limit: float } -- from Router only
    - Output      : { directive: str, mode: str, urgency: float, time_remaining: float }
    - Runs on every tick -- never sleeps, never blocks.
    - Guarantees the game never times out.

    Timing policy (spec)
    --------------------
        time_elapsed <= 540 s  -> NORMAL    -- planner decides freely
        540 < elapsed <= 570 s -> FAST_MOVE -- force fastest legal move immediately
        elapsed > 570 s        -> FORCE_PASS -- force pass to avoid timeout
    """
    logger = logging.getLogger(__name__)
    _PROJECT_ROOT = pathlib.Path(__file__).resolve().parent
    _LOG_PATH = _PROJECT_ROOT / 'logs' / 'reasoning_log.json'

    class TimeManager:

        def __init__(self, **kwargs: Any):
            self.log_dir = pathlib.Path(kwargs.get('log_dir')) if kwargs.get('log_dir') else _PROJECT_ROOT / 'logs'
            self._log_buffer: list[dict[str, Any]] = []

        def flush_logs(self) -> None:
            log_path = self.log_dir / 'reasoning_log.json'
            try:
                log_path.parent.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            flush_reasoning_logs(self._log_buffer, log_path, logger)

        def tick(self, packet: dict[str, Any]) -> dict[str, Any]:
            if hasattr(packet, 'model_dump'):
                packet = packet.model_dump()
            elif hasattr(packet, '_asdict'):
                packet = packet._asdict()
            elif hasattr(packet, '__dict__'):
                packet = packet.__dict__
            time_elapsed: float = float(packet.get('time_elapsed', 0.0))
            time_limit: float = float(packet.get('time_limit', 600.0))
            directive, mode = self._classify(time_elapsed, time_limit)
            urgency = self._urgency(time_elapsed, time_limit)
            time_remaining = max(0.0, time_limit - time_elapsed)
            result: dict[str, Any] = {'directive': directive, 'mode': mode, 'urgency': round(urgency, 4), 'time_remaining': round(time_remaining, 2)}
            self._log(packet, result, time_limit)
            return result
        receive = tick

        @staticmethod
        def _classify(time_elapsed: float, time_limit: float) -> tuple[str, str]:
            if time_elapsed > time_limit - 30.0:
                return ('FORCE_PASS', 'critical')
            if time_elapsed > time_limit - 60.0:
                return ('FAST_MOVE', 'urgent')
            return ('NORMAL', 'standard')

        @staticmethod
        def _urgency(time_elapsed: float, time_limit: float) -> float:
            if time_limit <= 0:
                return 1.0
            return min(1.0, max(0.0, time_elapsed / time_limit))

        def _log(self, packet, result, time_limit: float=600.0):
            entry: dict[str, Any] = {'timestamp': datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds') + 'Z', 'agent': 'TimeManager', 'input': packet, 'reasoning': {'threshold_fast': time_limit - 60.0, 'threshold_force_pass': time_limit - 30.0, 'evaluation': f'time_elapsed={packet.get('time_elapsed')} -> directive={result['directive']}'}, 'output': result}
            self._log_buffer.append(entry)

    # === agents/orchestrator_merge ===
    def _merge(gs, time_result, hand_result, plan_result, strat_result, opp_result) -> TurnDecision:
        try:
            final_actions = plan_result.get('action_sequence', ['PASS'])
            if time_result.get('directive', 'NORMAL') == 'FAST_MOVE':
                final_actions = final_actions[:1] if final_actions else ['PASS']
            primary_action = final_actions[0] if final_actions else 'PASS'
            return TurnDecision(timing_directive=time_result.get('directive', 'NORMAL'), time_remaining=time_result.get('time_remaining', 600.0), hand_score=hand_result.get('hand_score', 0.0), priority_profile=hand_result.get('priority_profile', 'defensive'), top_play=hand_result.get('top_play', 'PASS'), strategy=strat_result.get('strategy', 'unknown'), posture=strat_result.get('posture', 'defensive'), strategy_confidence=strat_result.get('confidence', 0.0), predicted_opponent_action=opp_result.get('predicted_next_action', 'unknown'), opponent_archetype=opp_result.get('inferred_deck_type', 'unknown'), opponent_confidence=opp_result.get('archetype_confidence', 0.0), final_actions=final_actions, primary_action=primary_action)
        except Exception:
            return _emergency_pass(time_result)

    def _emergency_pass(time_result) -> TurnDecision:
        return TurnDecision(timing_directive='FORCE_PASS', time_remaining=time_result['time_remaining'], hand_score=0.0, priority_profile='defensive', top_play='(time emergency)', strategy='time_critical', posture='defensive', strategy_confidence=1.0, predicted_opponent_action='unknown', opponent_archetype='unknown', opponent_confidence=0.0, final_actions=['PASS'], primary_action='PASS')

