    # === agents/mcts_node ===
    import threading

    class MCTSNode:

        def __init__(self, state_hash: str, parent=None, action_taken: str=None, prior_prob: float=1.0, is_chance_node: bool=False):
            self.state_hash = state_hash
            self.parent = parent
            self.action_taken = action_taken
            self.children: Dict[str, 'MCTSNode'] = {}
            self.visit_count = 0
            self.value_sum = 0.0
            self.prior_prob = prior_prob
            self.is_chance_node = is_chance_node
            self.is_pruned = False
            self.is_terminal = False
            self.virtual_loss = 0.0
            self._lock = threading.Lock()

        @property
        def q_value(self) -> float:
            if self.visit_count == 0:
                return 0.0
            return (self.value_sum + self.virtual_loss) / self.visit_count

        @property
        def real_q_value(self) -> float:
            if self.visit_count == 0:
                return 0.0
            return self.value_sum / self.visit_count

        def apply_virtual_loss(self, loss: float=-1.0):
            with self._lock:
                self.virtual_loss += loss
                self.visit_count += 1

        def revert_virtual_loss(self, loss: float=-1.0):
            with self._lock:
                self.virtual_loss -= loss
                self.visit_count -= 1

        def expand(self, action_priors: List[ActionPrior]):
            chance_actions = ['crushing_hammer', 'pokemon_catcher', 'super_scoop_up', 'pokeball']
            for ap in action_priors:
                if ap.action not in self.children:
                    is_chance = any((ca in ap.action.lower() for ca in chance_actions))
                    if is_chance:
                        chance_node = MCTSNode(state_hash=f'{self.state_hash}_{ap.action}_chance', parent=self, action_taken=ap.action, prior_prob=ap.prob, is_chance_node=True)
                        chance_node.children['heads'] = MCTSNode(state_hash=f'{self.state_hash}_{ap.action}_heads', parent=chance_node, action_taken=f'{ap.action}_heads', prior_prob=0.5)
                        chance_node.children['tails'] = MCTSNode(state_hash=f'{self.state_hash}_{ap.action}_tails', parent=chance_node, action_taken=f'{ap.action}_tails', prior_prob=0.5)
                        self.children[ap.action] = chance_node
                    else:
                        self.children[ap.action] = MCTSNode(state_hash=f'{self.state_hash}_{ap.action}', parent=self, action_taken=ap.action, prior_prob=ap.prob)

        def is_expanded(self) -> bool:
            return len(self.children) > 0 or self.is_terminal

    # === router/bus_routerbus ===
    logger = logging.getLogger(__name__)

    class RouterBus:

        def __init__(self, delegation_map: Dict[str, str], log_dir: str='logs'):
            self.delegation_map = delegation_map
            self.registry: Dict[str, Callable[[Any], Any]] = {}
            self.log_file = Path(log_dir) / 'action_log.json'
            self._action_buffer = []

        def register_agent(self, agent_name: str, callback: Callable[[Any], Any], perspective_flag: str=None):
            if agent_name == 'opponent_model' and perspective_flag != 'opponent':
                raise ValueError("opponent_model must have perspective_flag='opponent'")
            self.registry[agent_name] = callback

        def dispatch(self, event_name: str, packet: Any) -> Any:
            target_agent = self.delegation_map.get(event_name)
            if not target_agent:
                raise ValueError(f'No agent delegated for event: {event_name}')
            callback = self.registry.get(target_agent)
            if not callback:
                raise ValueError(f'No callback registered for agent: {target_agent}')
            packet_class = type(packet).__name__
            if packet_class in ('GameState', 'OrchestratorState'):
                raise PermissionError(f'Agent {target_agent} is blocked from receiving full game state!')
            if packet_class not in ALLOWED_PACKETS.get(target_agent, set()):
                raise PermissionError(f"Boundary Violation: Agent '{target_agent}' cannot receive '{packet_class}'")
            response = callback(packet)
            log_and_flush_delegation(self.log_file, self._action_buffer, event_name, target_agent, packet_class)
            return response

        def flush_logs(self):
            flush_reasoning_logs(self._action_buffer, self.log_file, logger)

    # === agents/belief_tracker ===
    logger = logging.getLogger(__name__)

    class BeliefTracker:

        def __init__(self, initial_deck: Dict[int, int]=None):
            self.state = BeliefState()
            self.assumed_deck = initial_deck or {}
            self.locked_prize_ids: set = set()
            self.prize_guaranteed_counts: Dict[int, int] = {}
            self._initialize_probabilities()

        def _initialize_probabilities(self):
            total_cards = sum(self.assumed_deck.values()) if self.assumed_deck else 60
            if total_cards == 0:
                return
            self.state.deck_size = total_cards - 7 - 6
            self.state.hand_size = 7
            self.state.prize_size = 6
            for card_id, count in self.assumed_deck.items():
                prob_in_deck = count / total_cards
                self.state.deck_probabilities[card_id] = prob_in_deck
                prob_in_hand = hypergeometric_prob(total_cards, count, 7)
                self.state.hand_probabilities[card_id] = prob_in_hand
                prob_in_prizes = hypergeometric_prob(total_cards, count, 6)
                self.state.prize_probabilities[card_id] = prob_in_prizes

        def update_on_play(self, card_id: int):
            card_id = int(card_id)
            self.state.hand_size = max(0, self.state.hand_size - 1)
            self.state.known_in_play[card_id] = self.state.known_in_play.get(card_id, 0) + 1
            if card_id in self.state.known_in_hand:
                self.state.known_in_hand[card_id] -= 1
                if self.state.known_in_hand[card_id] <= 0:
                    del self.state.known_in_hand[card_id]
            self._recalculate_probabilities()

        def update_on_draw(self, n: int):
            self.state.deck_size = max(0, self.state.deck_size - n)
            self.state.hand_size += n
            self._recalculate_probabilities()

        def update_on_search(self, card_id: int):
            self.state.deck_size = max(0, self.state.deck_size - 1)
            self.state.hand_size += 1
            self.state.known_in_hand[card_id] = self.state.known_in_hand.get(card_id, 0) + 1
            self._recalculate_probabilities()

        def update_on_discard(self, card_id: int):
            self.state.known_in_discard[card_id] = self.state.known_in_discard.get(card_id, 0) + 1
            self._recalculate_probabilities()

        def _recalculate_probabilities(self):
            recalculate_probabilities(self.state, self.assumed_deck, self.prize_guaranteed_counts)

        def lock_prizes(self, prized_ids: Dict[int, int], full_search: bool=True):
            self.locked_prize_ids.clear()
            self.prize_guaranteed_counts.clear()
            total_locked = 0
            for card_id in self.assumed_deck:
                count = prized_ids.get(card_id, 0)
                if count > 0:
                    self.state.prize_probabilities[card_id] = 1.0
                    self.locked_prize_ids.add(card_id)
                    self.prize_guaranteed_counts[card_id] = count
                    total_locked += count
                elif full_search:
                    self.state.prize_probabilities[card_id] = 0.0
            logger.info(f'BeliefTracker: locked {total_locked} prized cards ({len(prized_ids)} types) at 100% certainty')

        def get_threat_score(self) -> float:
            score = 0.0
            for prob in self.state.hand_probabilities.values():
                score += prob
            return score

        def sample_determinization(self) -> Dict[str, List[int]]:
            return sample_determinization(self.state, self.assumed_deck, self.prize_guaranteed_counts)

        def probability_opponent_holds(self, card_name: str) -> float:
            """
            P(opponent has >=1 copy of card_name in hand).
            Uses: P(X>=1) = 1 - C(N-D, H) / C(N, H)
            where N = opponent deck size + hand size (unknown cards pool), D = remaining copies, H = opponent hand size.
            """
            return probability_opponent_holds_helper(card_name, self.assumed_deck, self.state.deck_size, self.state.hand_size, self.state.known_in_play, self.state.known_in_discard)

    # === agents/card_registry ===
    logger = logging.getLogger(__name__)

    class CardRegistry:
        _instance = None

        def __new__(cls, skills_dir: str='skills'):
            if not cls._instance:
                cls._instance = super(CardRegistry, cls).__new__(cls)
                cls._instance._initialize(skills_dir)
            elif cls._instance.skills_dir != Path(skills_dir):
                cls._instance._initialize(skills_dir)
            return cls._instance

        def _initialize(self, skills_dir: str):
            self.skills_dir = Path(skills_dir)
            self.cards: Dict[Any, CardEntry] = {}
            self.full_cards: Dict[Any, CardEntry] = {}
            self.evolution_predecessors: Dict[str, str] = {}
            load_metadata_helper(self.skills_dir, self.cards, self.evolution_predecessors)

        def get(self, card_id: Any) -> Optional[CardEntry]:
            """Get lightweight metadata card entry."""
            return self.cards.get(card_id)

        def get_full_skill(self, card_id: Any) -> Optional[CardEntry]:
            """Lazy loads and returns the heavy full skill data for a card."""
            if card_id in self.full_cards:
                return self.full_cards[card_id]
            base = self.cards.get(card_id)
            if not base:
                return None
            ctx = SharedContext()
            heavy_data = ctx.get_config(str(self.skills_dir), 'card_scoring.json')
            if not hasattr(self, '_heavy_cards_index'):
                self._heavy_cards_index = {str(c.get('card_id', '')): c for c in heavy_data.get('cards', [])}
            card_data = self._heavy_cards_index.get(str(base.card_id))
            if not card_data:
                self.full_cards[card_id] = base
                return base
            trainer_subtype = TrainerSubtype.NONE
            if base.card_type == CardType.TRAINER:
                raw_stage_type = card_data.get('stage_type', '').lower()
                for key, val in TRAINER_MAP.items():
                    if key in raw_stage_type:
                        trainer_subtype = val
                        break
            combo_mask = ComboTag.NONE
            for tag in card_data.get('combo_tags', []):
                tag_enum = COMBO_TAG_MAP.get(tag)
                if tag_enum:
                    combo_mask |= tag_enum
            entry = CardEntry(card_id=base.card_id, card_name=base.card_name, card_type=base.card_type, stage=base.stage, trainer_subtype=trainer_subtype, combo_tags=combo_mask, ev_score=float(card_data.get('ev_score', 0.0)), damage_output=int(card_data.get('damage_output', 0)), energy_cost=int(card_data.get('energy_cost', 0)), utility_score=float(card_data.get('utility_score', 0.0)), archetype=card_data.get('archetype', ''), previous_stage=base.previous_stage, is_full=True)
            self.full_cards[base.card_id] = entry
            self.full_cards[str(base.card_id)] = entry
            return entry

        def get_evolution_predecessor(self, card_name: str) -> str:
            """Returns the name of the previous stage, or empty string."""
            return self.evolution_predecessors.get(card_name.lower(), '')

    # === agents/hand_analyst_metrics ===

    class HandMetricsMixin:

        def calculate_metrics(self, hand: List[str], board: List[str], turn: int, opponent_prizes: int, deck_remaining: int) -> dict:
            ev_scores, hand_cards_data, flags = self.eval_hand_cards(hand, self.registry)
            if not ev_scores:
                return {'hand_score': 0.0, 'priority_profile': 'setup', 'top_play': 'none', 'reasoning_chain': 'Empty evaluations.'}
            cfg = unpack_ha_config(self.strategy_thresholds)
            phase = 'early' if turn <= 3 else 'mid' if turn <= 8 else 'late'
            avg_ev = sum(ev_scores) / len(ev_scores)
            multiplier, bonus = self.get_multipliers_and_bonuses(flags, self.strategy_tips, cfg, flags['supporter_count'])
            brick_penalty, evo_bonus = self.eval_bricks_evo(hand, board, self.registry, cfg)
            bonus += brick_penalty
            multiplier += evo_bonus
            bonus += self.apply_phase_bonuses(phase, flags, hand_cards_data, cfg)
            hand_score = min(1.0, max(0.0, (avg_ev + bonus) * multiplier))
            has_attacker = any((getattr(c[0], 'damage_output', 0) > 0 for c in hand_cards_data if getattr(c[0], 'card_type', '') == 'Pokemon' or getattr(getattr(c[0], 'card_type', None), 'name', '') == 'POKEMON'))
            has_evolution = any((getattr(c[0], 'card_type', '') == 'Pokemon' and 'Stage' in getattr(c[0], 'card_name', '') for c in hand_cards_data))
            control_count = sum((1 for c in hand_cards_data if getattr(c[0], 'archetype', '') == 'control'))
            metrics = {'opponent_prizes': opponent_prizes, 'hand_score': hand_score, 'has_attacker': has_attacker, 'has_energy': flags['has_energy'], 'has_basic': flags['has_basic'], 'has_evolution': has_evolution, 'control_count': control_count, 'deck_remaining': deck_remaining}
            priority_profile = self.resolve_priority_profile(metrics, cfg, phase)
            top_play = self.get_sorted_top_play(hand_cards_data)
            return {'hand_score': round(hand_score, 4), 'priority_profile': priority_profile, 'top_play': top_play, 'reasoning_chain': f'Hand score {round(hand_score, 4)}, profile {priority_profile} resolved.'}

    # === agents/hand_analyst_rules ===

    class HandRulesMixin:

        def resolve_priority_profile(self, metrics: dict, config: dict, phase: str) -> str:
            opp_prizes = metrics['opponent_prizes']
            hand_score = metrics['hand_score']
            if opp_prizes <= config['closing_opp_prizes'] and metrics['has_attacker']:
                return 'closing'
            elif metrics['has_attacker'] and metrics['has_energy'] and (hand_score > config['aggro_push_hand_score']):
                return 'aggro_push'
            elif metrics['has_basic'] and (not metrics['has_energy']) or (metrics['has_evolution'] and (not metrics['has_basic'])) or hand_score < config['setup_hand_score']:
                return 'setup'
            elif metrics['control_count'] >= config['disruption_control_count'] and opp_prizes <= config['disruption_opp_prizes']:
                return 'disruption'
            elif metrics['deck_remaining'] < config['stall_deck_remaining'] and (not metrics['has_attacker']):
                return 'stall'
            return 'setup' if phase == 'early' else 'aggro_push'

        def get_sorted_top_play(self, hand_cards_data: List[tuple]) -> str:

            def sort_key(item):
                card, ev = item
                ctype = getattr(card, 'card_type', 'Trainer')
                if ctype == 'Pokemon' or (hasattr(ctype, 'name') and ctype.name == 'POKEMON'):
                    type_priority = 3
                elif ctype == 'Trainer' or (hasattr(ctype, 'name') and ctype.name == 'TRAINER'):
                    type_priority = 2
                else:
                    type_priority = 1
                return (ev, type_priority)
            hand_cards_data.sort(key=sort_key, reverse=True)
            top_play_card = hand_cards_data[0][0]
            return getattr(top_play_card, 'card_name', getattr(top_play_card, 'card_id', 'none'))

    # === agents/mcts_selection ===
    logger = logging.getLogger(__name__)

    class MCTSSelectionMixin:

        def calculate_ucb(self, node: MCTSNode, total_parent_visits: int, c_puct: float) -> float:
            """Calculates the PUCT (Predictor Upper Confidence bound for Trees) score."""
            q_value = node.q_value
            u_value = c_puct * node.prior_prob * math.sqrt(total_parent_visits) / (1 + node.visit_count)
            return q_value + u_value

        def select_child(self, node: MCTSNode, c_puct: float) -> MCTSNode:
            """Selects the child with the highest UCB score, or samples probabilistically for chance nodes."""
            if node.is_chance_node:
                return self._sample_chance_child(node)
            best_score = -float('inf')
            best_child = None
            for child in node.children.values():
                if child.is_pruned:
                    continue
                score = self.calculate_ucb(child, node.visit_count, c_puct)
                if score > best_score:
                    best_score = score
                    best_child = child
            if not best_child and node.children:
                best_child = list(node.children.values())[0]
            return best_child

        def _sample_chance_child(self, node: MCTSNode) -> MCTSNode:
            """Sample a child from a chance node proportional to prior probabilities."""
            r = random.random()
            cumulative = 0.0
            for child in node.children.values():
                cumulative += child.prior_prob
                if r <= cumulative:
                    return child
            return list(node.children.values())[-1]

    # === router/bus ===
    __all__ = ['HandAnalystPacket', 'TurnPlannerPacket', 'StrategyPacket', 'TimePacket', 'OpponentModelPacket', 'LethalPacket', 'Router', 'ScopeViolationError', 'UnknownAgentError', 'PACKET_SCHEMAS', 'RouterBus']

    # === agents/forward_model_resolve ===

    def _resolve_base(gs: dict, hand: list, action: str) -> None:
        parts = action.split(':', 1)
        act_type = parts[0]
        target = parts[1] if len(parts) > 1 else ''
        if act_type == 'pass':
            gs['turn_ended'] = True
        elif act_type == 'bench':
            _remove_from_hand(hand, _int_or_str(target))
            gs['my_hand'] = hand
            bench = list(gs.get('my_bench', []))
            bench.append({'id': _int_or_str(target), 'hp': 100, 'attached': []})
            gs['my_bench'] = bench
        elif act_type == 'evolve':
            _apply_evolve(gs, _int_or_str(target))
        elif act_type == 'attach_energy':
            card_target = target.split(':', 1)
            card_id = card_target[0]
            poke_id = card_target[1] if len(card_target) > 1 else None
            _remove_from_hand(hand, _int_or_str(card_id))
            gs['my_hand'] = hand
            valid_targets = []
            if isinstance(gs.get('my_active_pokemon'), dict):
                valid_targets.append(gs['my_active_pokemon'])
            bench = gs.get('my_bench', [])
            if isinstance(bench, list):
                valid_targets.extend([p for p in bench if isinstance(p, dict)])
            if valid_targets:
                chosen = None
                if poke_id:
                    for p in valid_targets:
                        if str(p.get('id')) == poke_id:
                            chosen = p
                            break
                if not chosen:
                    import random
                    chosen = random.choice(valid_targets)
                attached = list(chosen.get('attached', []))
                attached.append(card_id)
                chosen['attached'] = attached
        elif act_type == 'retreat':
            handle_retreat_helper(gs, target, CardRegistry)
        elif act_type == 'attack':
            handle_attack_helper(gs, hand, CardRegistry)
        elif act_type == 'play_trainer':
            handle_play_trainer_helper(gs, hand, target, CardRegistry, _int_or_str, _remove_from_hand, _draw_cards)
        elif act_type == 'ability':
            name = target.lower() if target else ''
            if any((k in name for k in _ABILITY_DRAW)):
                gs['my_hand'] = _draw_cards(hand, gs, 3)

    # === agents/heuristic_pipeline_check ===
    """
    Sub-module: check_lethal, mask_illegal, _calc_sig
    """
    logger = logging.getLogger(__name__)
    _registry = CardRegistry()

    def check_lethal(my_damage: int, opp_hp: int, legal_attacks: list, opp_active_id, my_hp: int, legal_retreats: list, my_attached: int=0) -> dict:
        if legal_attacks and my_damage >= opp_hp and (my_damage > 0):
            best_attack = legal_attacks[0]
            reasoning = f'Lethal: my_damage {my_damage} >= opp_hp {opp_hp}'
            best_attack_name = str(best_attack).replace('attack:', '')
            return {'action_override': f'attack:{best_attack_name}', 'reasoning_chain': reasoning}
        if opp_active_id is not None:
            try:
                opp_card = CardRegistry().get_full_skill(opp_active_id)
                if opp_card and opp_card.damage_output >= my_hp and (opp_card.damage_output > 0):
                    if legal_retreats:
                        can_counter = my_damage >= opp_hp and my_attached > 0
                        if not can_counter:
                            tgt = legal_retreats[0]
                            reasoning = f'Opponent lethal threat (damage {opp_card.damage_output} >= HP {my_hp}). Boost retreat:{tgt} +1.0'
                            return {'action_override': None, 'retreat_score_boost': 1.0, 'retreat_target': tgt, 'reasoning_chain': reasoning}
            except Exception as e:
                logger.error(f'check_lethal registry error: {e}')
        return {'action_override': None, 'reasoning_chain': 'No lethal found.'}

    def mask_illegal(legal_actions: list, game_state: dict) -> list:
        if not legal_actions:
            return ['pass']
        filtered = []
        my_bench = game_state.get('my_bench', [])
        my_hand = game_state.get('my_hand', [])
        my_deck_count = game_state.get('my_deck_count', 60)
        for action in legal_actions:
            if action.startswith('retreat:') and (not my_bench):
                continue
            if action.startswith('play_trainer:') and my_deck_count <= 0:
                trainer_name = action.split(':', 1)[1].lower() if ':' in action else ''
                if any((k in trainer_name for k in ['research', 'iono', 'judge', 'draw'])):
                    continue
            filtered.append(action)
        return filtered or ['pass']

    def _calc_sig(action: str, bench_sigs: Dict[int, str], gs: dict) -> str:
        parts = action.split(':')
        if len(parts) < 2:
            return action
        target = parts[1]
        if target.startswith('bench_'):
            try:
                idx = int(target.split('_')[1])
                if idx in bench_sigs:
                    return f'{parts[0]}:bench_sig_{bench_sigs[idx]}'
            except (ValueError, IndexError):
                pass
        return action

    # === agents/heuristic_pipeline_eval ===
    """
    Sub-module: score_action, score_state
    """
    logger = logging.getLogger(__name__)
    _registry = CardRegistry()

    def score_action(action: str, gs: dict, threat: float=0.0) -> float:
        v = 0.0
        dc = gs.get('my_deck_count', 60)
        mp = gs.get('my_prizes', 6)
        ahp = gs.get('my_active_hp', 100)
        bn = gs.get('my_bench', [])
        ac = gs.get('my_active_pokemon', {})
        if action.startswith('attack:'):
            v += 0.5
            if mp <= 1:
                v += 0.5
            opp_ac = gs.get('opponent_active_pokemon', {})
            if isinstance(ac, dict) and isinstance(opp_ac, dict):
                my_type = ac.get('element_type', '')
                opp_weak = opp_ac.get('weakness', '')
                if my_type and opp_weak and (my_type.lower() == opp_weak.lower()):
                    v += 0.4
        elif action.startswith('evolve:'):
            v += 0.3
        elif action.startswith('attach_energy:'):
            v += 0.2
            if isinstance(ac, dict):
                need = 2
                try:
                    e = _registry.get_full_skill(ac.get('id'))
                    if e and e.energy_cost > 0:
                        need = e.energy_cost
                except:
                    pass
                att = len(ac.get('attached', []))
                if att >= need:
                    an = ac.get('card_name', '').lower()
                    sc = any((sa in an for sa in {'raging bolt', 'iron hands', 'chien pao', 'ceruledge', 'garchomp', 'roaring moon', 'groudon', 'kyogre'}))
                    nr = ahp <= 50 or gs.get('my_active_status', '') in {'poisoned', 'burned', 'asleep', 'paralyzed'}
                    if not sc and (not nr):
                        v -= 0.15
        elif action.startswith('bench:'):
            if not bn:
                v += 0.8
            else:
                v += 0.15
                bs = len(bn)
                pr = gs.get('priority_profile', 'aggro_push')
                tol = {'aggro_push': 0.15, 'closing': 0.1, 'disruption': -0.05, 'setup': 0.15, 'stall': -0.15}.get(pr, 0.0)
                if bs >= 4 and tol < 0:
                    v += tol * bs * 0.3
                elif bs >= 5 and tol <= 0:
                    v -= 0.4
        elif action.startswith('play_trainer:'):
            v += 0.4
            if dc <= 5:
                tn = action.split(':', 1)[1].lower()
                if any((k in tn for k in {'iono', 'judge'})):
                    v += 0.8
                elif any((k in tn for k in {'research', 'professor'})):
                    v -= 1.3
            if dc > 30:
                n = action.split(':', 1)[1].lower()
                sk = {'nest ball', 'ultra ball', 'quick ball', 'level ball', 'secret box', 'mega signal', "team rocket's petrel"}
                if any((s in n for s in sk)):
                    v += min(0.25, dc * 0.005)
        elif action.startswith('ability:'):
            tn = action.split(':', 1)[1].lower()
            v += 0.35
            if dc <= 5 and any((d in tn for d in {'colress', 'concealed'})):
                v -= 0.5
        elif action.startswith('retreat:'):
            v += 0.4 if ahp <= 60 else -0.2
            rsb = gs.get('retreat_score_boost', 0.0)
            if rsb > 0:
                v += rsb
        elif action == 'pass':
            v -= 0.5
        hs = len(gs.get('my_hand', [])) if isinstance(gs.get('my_hand'), list) else 0
        if hs >= 2 and dc > 10:
            v += 0.03 * min(hs, 5)
        return v

    def score_state(gs: dict) -> float:
        v = 0.0
        v += 0.15 * (gs.get('opponent_prizes', 6) - gs.get('my_prizes', 6))
        v += 0.001 * (gs.get('my_active_hp', 100) - gs.get('opponent_active_hp', 100))
        all_p = gs.get('my_bench', []) + ([gs.get('my_active_pokemon', {})] if isinstance(gs.get('my_active_pokemon'), dict) and gs.get('my_active_pokemon') else [])
        ec = 0
        for p in all_p:
            if isinstance(p, dict) and p.get('id'):
                try:
                    ce = _registry.get(p['id'])
                    if ce and ce.stage in (CardStage.STAGE1, CardStage.STAGE2):
                        ec += 1
                except:
                    pass
        v += 0.05 * ec
        return v

    # === agents/heuristic_pipeline_search ===
    """
    Sub-module: thinning_value, pick_best_search, dead_weight
    """
    logger = logging.getLogger(__name__)
    _registry = CardRegistry()
    _SEARCH_KEYWORDS = {'ultra', 'nest', 'level', 'heavy', 'quick', 'pokeball', 'signal', 'secret box', 'petrel', 'earthen vessel'}

    def thinning_value(candidate: str, game_state: dict) -> float:
        if not candidate.startswith('play_trainer:'):
            return 0.0
        name = candidate.split(':', 1)[1].lower()
        if not any((sk in name for sk in _SEARCH_KEYWORDS)):
            return 0.0
        dc = game_state.get('my_deck_count', 60)
        return 0.3 if dc > 45 else 0.15 if dc > 30 else 0.0

    def pick_best_search(candidates: list) -> Optional[str]:
        best, bs = (None, -1)
        for cand in candidates:
            if cand.startswith('play_trainer:'):
                target = cand.split(':', 1)[1].lower()
                if any((sk in target for sk in _SEARCH_KEYWORDS)):
                    score = 4 if 'secret box' in target else 3 if 'ultra' in target else 2 if 'nest' in target else 1
                    if score > bs:
                        bs, best = (score, cand)
        return best

    def dead_weight(candidates: list, gs: dict) -> bool:
        try:
            hand = gs.get('my_hand', [])
            if not isinstance(hand, list) or len(hand) < 4:
                return False
            unplayable = 0
            total_supporters = 0
            for cid in hand:
                try:
                    c = _registry.get(int(cid))
                    if not c:
                        continue
                    if c.card_type.name == 'TRAINER' and getattr(c, 'trainer_subtype', None) and (c.trainer_subtype.name == 'SUPPORTER'):
                        total_supporters += 1
                    elif c.stage and c.stage.name == 'STAGE2':
                        unplayable += 1
                except:
                    pass
            if total_supporters > 1:
                unplayable += total_supporters - 1
            return unplayable >= 4
        except Exception as e:
            logger.error(f'dead_weight failed: {e}')
            return False

    # === agents/prized_helpers ===
    _registry = CardRegistry()

    def prized_pokemon_probs(prized_probabilities: dict, decklist: dict=None) -> list:
        probs = []
        try:
            for cid_str, prob in prized_probabilities.items():
                card = _registry.get(int(cid_str))
                if card and card.card_type == CardType.POKEMON:
                    if decklist:
                        count = decklist.get(int(cid_str), decklist.get(cid_str, 0))
                        if count < 2:
                            continue
                    probs.append(prob)
        except:
            probs = list(prized_probabilities.values())
        return probs

