    class HandRunMixin:

        def run_hand_analyst(self, packet: Any) -> dict:
            """Executes hand analysis, tracking prized probabilities and computing scores."""
            if not isinstance(packet, HandAnalystPacket):
                raise TypeError('HandAnalyst got illegal packet type.')
            hand = packet.hand
            deck_remaining = packet.deck_remaining
            turn = getattr(packet, 'turn', 1)
            opponent_prizes = getattr(packet, 'opponent_prizes_remaining', 6)
            discard = getattr(packet, 'discard', []) or []
            board = getattr(packet, 'board', []) or []
            has_searched_deck = getattr(packet, 'has_searched_deck', False)
            prize_remaining, total_unrevealed, prized_probabilities = self.evaluate_prizes(hand, discard, board, self.deck_base_list, deck_remaining, has_searched_deck=has_searched_deck)
            if prized_probabilities:
                self._prize_mapper_buffer.append({'turn': turn, 'perspective': self.perspective_flag, 'prize_remaining': prize_remaining, 'total_unrevealed': total_unrevealed, 'prized_probabilities': prized_probabilities})
            if not hand:
                response = {'hand_score': 0.0, 'priority_profile': 'stall', 'top_play': 'none', 'reasoning_chain': 'Empty hand — stall profile activated', 'prized_probabilities': {}}
                self._log_reasoning(turn, response)
                return response
            response = self.calculate_metrics(hand, board, turn, opponent_prizes, deck_remaining)
            response['prized_probabilities'] = prized_probabilities
            self._log_reasoning(turn, response)
            return response

    # === agents/opponent_model ===
    logger = logging.getLogger(__name__)

    @register_agent('opponent_model', perspective_flag='opponent')
    class OpponentModel(BaseAgent):

        def __init__(self, log_dir: str='logs', skills_dir: str='skills', perspective_flag: str='opponent', shared_context=None):
            super().__init__(perspective_flag)
            self.log_dir = Path(log_dir)
            self.skills_dir = Path(skills_dir)
            self.shared_context = shared_context
            try:
                self.log_dir.mkdir(parents=True, exist_ok=True)
                self.skills_dir.mkdir(parents=True, exist_ok=True)
            except Exception as e:
                logger.warning(f'Could not create opponent model directories: {e}')
            self.reasoning_log_file = self.log_dir / 'opponent_model_reasoning.json'
            self._reasoning_buffer = []
            if self.shared_context:
                self.archetypes = self.shared_context.get_config(str(self.skills_dir), 'deck_archetypes.json').get('archetypes', {})
            else:
                self.archetypes = self._load_deck_archetypes()
            self.revealed_state = []
            self.inferred_state = {}
            self.archetype_confidence = 0.0
            self.identified_archetype = 'unknown'
            self.opponent_searched_last_turn = False

        def _load_deck_archetypes(self) -> dict:
            path = self.skills_dir / 'deck_archetypes.json'
            if path.exists():
                try:
                    data = json.loads(path.read_text(encoding='utf-8'))
                    return data.get('archetypes', {})
                except Exception as e:
                    logger.error(f'Failed to read deck_archetypes.json: {e}')
            return {}

        def receive(self, packet: Any) -> dict:
            if hasattr(packet, '_asdict'):
                packet = packet._asdict()
            elif hasattr(packet, '__dict__'):
                packet = packet.__dict__
            if not isinstance(packet, dict):
                raise TypeError(f'OpponentModel received illegal packet type: {type(packet).__name__}.')
            revealed_cards = packet.get('revealed_cards') or packet.get('newly_played_cards', [])
            turn_number = packet.get('turn_number') or packet.get('turn', 1)
            prizes_remaining = packet.get('prizes_remaining') or packet.get('revealed_prizes_remaining', 6)
            for card in revealed_cards:
                if card not in self.revealed_state:
                    self.revealed_state.append(card)
            self.identified_archetype, self.archetype_confidence = identify_opponent_archetype(self.revealed_state, self.archetypes)
            if self.identified_archetype != 'unknown' and self.identified_archetype in self.archetypes:
                pool = self.archetypes[self.identified_archetype].get('card_pool', [])
                self.inferred_state = {c: 1.0 for c in pool if c not in self.revealed_state}
            else:
                self.inferred_state = {}
            predicted = predict_opponent_action(self.identified_archetype, prizes_remaining, turn_number)
            reasoning = f'Identified {self.identified_archetype} with {round(self.archetype_confidence * 100, 2)}% confidence. Predicting {predicted}.'
            self._reasoning_buffer.append({'turn': turn_number, 'perspective': self.perspective_flag, 'revealed_count': len(self.revealed_state), 'identified_archetype': self.identified_archetype, 'confidence': self.archetype_confidence, 'predicted_next_action': predicted, 'reasoning': reasoning, 'opponent_searched_last_turn': self.opponent_searched_last_turn})
            return {'predicted_next_action': predicted, 'archetype_confidence': self.archetype_confidence, 'inferred_deck_type': self.identified_archetype, 'reasoning': reasoning, 'opponent_searched_last_turn': self.opponent_searched_last_turn}

        def flush_logs(self):
            if not self._reasoning_buffer:
                return
            try:
                with open(self.reasoning_log_file, 'a', encoding='utf-8') as f:
                    for entry in self._reasoning_buffer:
                        f.write(json.dumps(entry) + '\n')
                self._reasoning_buffer.clear()
            except Exception as e:
                logger.error(f'Failed to flush opponent model reasoning logs: {e}')

